cd /workspace/submission/src/offline && python3 - <<'EOF'
import re
src = open('ReceiveAudit.java').read()

# 1. Env gains a 'next' field
src = src.replace("""    private static final class Env {
        int level, phase, pnWidth, off;""",
"""    private static final class Env {
        int level, phase, pnWidth, off, next;""")

# 2. parseHeader: set next for long header
src = src.replace("""            e.payload = Arrays.copyOfRange(w, p[0], p[0] + (int) (len - e.pnWidth));
            return e;""",
"""            e.payload = Arrays.copyOfRange(w, p[0], p[0] + (int) (len - e.pnWidth));
            e.next = p[0] + (int) (len - e.pnWidth);
            return e;""")

# 3. parseHeader: set next for short header
src = src.replace("""            e.payload = Arrays.copyOfRange(w, p[0], w.length);
            return e;""",
"""            e.payload = Arrays.copyOfRange(w, p[0], w.length);
            e.next = w.length;
            return e;""")

# 4. processDatagram: use env.next; drop headerSize helper
src = src.replace("            off = env.off + headerSize(env) ;", "            off = env.next;")
src = src.replace("""    /** Bytes consumed by this envelope inside its datagram (header + pn + payload). */
    private static int headerSize(Env e) {
        // recompute from payload + pn width + known header overhead
        return e.consumed;
    }

""", "")

# 5. processEnvelope: reset curHash at entry
src = src.replace("""        Long epochOut = null;
        String status;
        String hash = null;""",
"""        Long epochOut = null;
        String status;
        String hash = null;
        curHash = null;""")

open('ReceiveAudit.java','w').write(src)
print("patched")
EOF
